CREATE TABLE new_artists (
  name VARCHAR(100),
  genre VARCHAR(50),
  city VARCHAR(100),
  state VARCHAR(100)
);
INSERT INTO new_artists (name, genre, city, state) VALUES
  ('Luna Ray', 'Pop', 'Austin', 'TX'),
  ('Sothea', 'Indie', 'Phnom Penh', 'KH'),
  ('Blaze Carter', 'Hip-Hop', 'Detroit', 'MI');
SELECT * FROM new_artists ORDER BY name;

CREATE TABLE demo_songs (
  song_title VARCHAR(100),
  artist_name VARCHAR(100),
  submission_date DATE
);
INSERT INTO demo_songs (song_title, artist_name, submission_date) VALUES
  ('Sunset City', 'Luna Ray', '2024-06-01'),
  ('River Lights', 'Sothea', '2024-06-02');
SELECT * FROM demo_songs ORDER BY submission_date;
